/* Generated by scripts/legacy-menu-port.py from the legacy café menu site (index.html <script>) — the frame engine,
   cart and WhatsApp ordering are kept as is. Config/data/frames come from #armada-menu-cfg; language from the page. */
/* CONFIG, DATA, FRAMES and the page language come from the #armada-menu-cfg JSON the page emits (content/menu.json + contact.json) */
const CFG = JSON.parse(document.getElementById("armada-menu-cfg").textContent);
const CONFIG = CFG.config;
const MODE = "files";
const DATA = CFG.data;
const FRAMES = CFG.frames;

const I18N = {
  ar:{skip:"تخطَّ إلى القائمة",cart:"السلة",yourOrder:"طلبك",total:"الإجمالي",sar:"ر.س",kcal:"سعرة",items:"صنف",add:"أضف",remove:"إزالة",
      empty:"سلتك فارغة. أضف ما يعجبك من القائمة.",hours:"يُقدَّم من {o} إلى {c}",clear:"مسح",clearAll:"مسح الاختيارات والرجوع للمنيو",cleared:"تم مسح الاختيارات",
      waContact:"تواصل معنا عبر واتساب",pdf:"تحميل المنيو PDF",follow:"تابعنا وخلك أول من يعرف جديدنا",wa:"أرسل الطلب عبر واتساب",copy:"انسخ تفاصيل الطلب",copied:"تم نسخ تفاصيل الطلب",
      hintNoNumber:"رقم واتساب الطلبات لم يُضبط بعد. انسخ تفاصيل الطلب وأرسلها للفريق.",hintNumber:"يفتح واتساب برسالة جاهزة تحوي الأصناف والكميات والإجمالي.",
      pending:"يُؤكَّد مع الفريق",pendNote:"الأصناف الموسومة لا تزال قيد التأكيد؛ اسأل فريقنا عن توفرها وسعرها.",
      view:"توسيع القائمة",hide:"تصغير",orderLine:"الكمية",unit:"سعر الوحدة",vipCta:"اطلب التجربة",orderTitle:"طلب من منيو أرمادا ريزيدنس",addr:"أرمادا ريزيدنس · طريق المطار، الطائف",guest:"نزلاء الفندق: التحويلة 333 من هاتف الغرفة",
      chooseOpt:"اختر:",still:"عرض ثابت — تم تفعيل تقليل الحركة",loading:"تحميل المشهد"},
  en:{skip:"Skip to menu",cart:"Cart",yourOrder:"Your order",total:"Total",sar:"SAR",kcal:"kcal",items:"items",add:"Add",remove:"Remove",
      empty:"Your cart is empty. Add anything you like from the menu.",hours:"Served {o}–{c}",clear:"Clear",clearAll:"Clear selection & back to menu",cleared:"Selection cleared",
      waContact:"Chat with us on WhatsApp",pdf:"Download menu (PDF)",follow:"Follow us and be the first to know what's new",wa:"Send order on WhatsApp",copy:"Copy order details",copied:"Order details copied",
      hintNoNumber:"The ordering WhatsApp number isn't set yet. Copy the order details and send them to our team.",hintNumber:"Opens WhatsApp with a ready message listing items, quantities and the total.",
      pending:"Ask our team",pendNote:"Marked items are still being confirmed; ask our team for availability and price.",
      view:"Expand list",hide:"Collapse",orderLine:"Qty",unit:"Unit price",vipCta:"Order the experience",orderTitle:"Order from the ARMADA RESIDENCE menu",addr:"ARMADA RESIDENCE · Airport Road, Taif",guest:"Hotel guests: dial 333 from your room phone",
      chooseOpt:"Choose:",still:"Still view — reduced motion is on",loading:"Loading scene"}
};

/* ---------- state ---------- */
const lang = CFG.lang;   // the site header switches /menu/ ↔ /en/menu/
let cart = {};        // key -> {id,opt,qty}
try{ const s=JSON.parse(localStorage.getItem("armada-menu")||"{}"); if(s.cart) cart=s.cart; }catch(e){}
const T = k => I18N[lang][k];
const RM = matchMedia("(prefers-reduced-motion: reduce)").matches;
const isNarrow = () => innerWidth<=820 || innerHeight>=innerWidth;

const itemsById = {}; DATA.items.forEach(i=>itemsById[i.id]=i);
const name = (it) => lang==="ar" ? it.name_ar : (it.name_en||it.name_ar);
const secName = (s) => lang==="ar" ? s.label_ar : s.label_en;
const subName = (s,k) => lang==="ar" ? k : (DATA.subcats_en[k]||k);
const fmt = n => `<span class="price"><span class="num">${n}</span><i>${T("sar")}</i></span>`;

const vipAvailable = CONFIG.vipOverride!==null ? !!CONFIG.vipOverride : (DATA.vip && DATA.vip.availability_status==="confirmed");
/* VIP is appended as a featured-card scene only when confirmed AND its frame set is present in this build */
function localHour(){ try{ return +new Intl.DateTimeFormat("en-GB",{hour:"numeric",hour12:false,timeZone:CONFIG.timeZone}).format(new Date()); }catch(e){ return new Date().getHours(); } }
const ORDER = localHour() < CONFIG.breakfastFirstUntilHour ? CONFIG.morningOrder : CONFIG.dayOrder;
const byId = {}; DATA.sections.forEach(s=>byId[s.id]=s);
function sectionOpen(id){ const h=CONFIG.serviceHours[id]; if(!h) return true; const n=localHour(); return n>=h.open && n<h.close; }
const CLOSED = ORDER.filter(id=>byId[id] && !sectionOpen(id));
const SECTIONS = ORDER.map(id=>byId[id]).filter(s=>s && sectionOpen(s.id)).concat(DATA.sections.filter(s=>s.id!=="vip_optional" && !ORDER.includes(s.id))).concat(
  (vipAvailable && FRAMES[DATA.vip.folder]) ? [{id:"vip_optional",folder:DATA.vip.folder,label_ar:DATA.vip.label_ar,label_en:DATA.vip.label_en,subcategories:[],items:[],featured:DATA.vip.item}] : []);

/* ---------- build scenes ---------- */
const main = document.getElementById("scenes");
const rail = document.getElementById("rail");
const scenes = []; // runtime per scene

function buildScenes(){
  main.innerHTML=""; rail.innerHTML="";
  SECTIONS.forEach((sec,si)=>{
    const len = RM?1:(sec.id==="snacks"?CONFIG.snacksLength:CONFIG.sceneLength);
    const el=document.createElement("section"); el.className="scene"; el.id="s-"+sec.id; el.style.setProperty("--len",len);
    el.innerHTML=`<div class="stage${RM?" rm":""}">
      <canvas class="glow" aria-hidden="true"></canvas>
      <canvas class="frame" role="img" aria-label=""></canvas>
      <div class="overlay">
        <div class="ttl"><h2></h2><p class="sub"></p><div class="hair"></div></div>
        <div class="panel"><div class="grps"></div></div>
      </div>
      <div class="lo"></div>
    </div>`;
    main.appendChild(el);
    const b=document.createElement("button"); b.dataset.sec=sec.id; b.addEventListener("click",()=>{ document.getElementById("s-"+sec.id).scrollIntoView({behavior:RM?"auto":"smooth"}); });
    rail.appendChild(b);
    const fr = FRAMES[sec.folder];
    if(sec.featured){ el.querySelector(".panel").remove(); const c=document.createElement("div"); c.className="vipcard"; el.querySelector(".overlay").appendChild(c); }
    scenes.push({sec,el,stage:el.querySelector(".stage"),glow:el.querySelector(".glow"),frame:el.querySelector(".frame"),
      ttl:el.querySelector(".ttl"),panel:el.querySelector(".panel"),grps:el.querySelector(".grps"),lo:el.querySelector(".lo"),
      card:el.querySelector(".vipcard"), count:fr.count, imgs:new Array(fr.count), loaded:0, drawn:-1, idx:0, maxP:0, visible:false,
      url:i=> MODE==="inline"?fr.urls[i]:fr.sets[frameSet()].pattern.replace("%04d",String(i).padStart(4,"0"))});
  });
  CLOSED.forEach(id=>{ const h=CONFIG.serviceHours[id]; const b=document.createElement("button"); b.className="closed"; b.disabled=true; b.dataset.sec=id;
    const t=x=>lang==="ar"?(x<12?`${x} ص`:`${x===12?12:x-12} م`):(x<12?`${x} AM`:`${x===12?12:x-12} PM`);
    b.dataset.hrs=JSON.stringify([h.open,h.close]); rail.appendChild(b); });
  const pl=document.createElement("a"); pl.className="pdf"; pl.href=document.getElementById("pdfTop").href; pl.target="_blank"; pl.rel="noopener"; pl.textContent="PDF"; rail.appendChild(pl);
  renderText();
  setupCanvases();
}


function renderText(){
  document.querySelectorAll("[data-i18n]").forEach(n=>n.textContent=T(n.dataset.i18n));
  scenes.forEach(sc=>{
    const s=sc.sec;
    sc.frame.setAttribute("aria-label", secName(s));
    sc.ttl.querySelector("h2").textContent=secName(s);
    const approved=s.items.filter(i=>i.approved && !CONFIG.hiddenItems.includes(i.id)).length;
    sc.ttl.querySelector(".sub").textContent = `${approved} ${T("items")}`;
    sc.lo.textContent=T("loading");
    if(sc.card){ const f=s.featured; sc.card.innerHTML=`<h3>${lang==="ar"?f.name_ar:f.name_en}</h3><p>${lang==="ar"?(f.desc_ar||""):(f.desc_en||"")}</p>${f.approved?`<div class="row" data-item="${f.id}"><span class="chip"><span class="nm">${lang==="ar"?f.name_ar:f.name_en}</span></span><span class="chip">${fmt(f.price_sar)}<button class="add" aria-label="${T("add")}">+</button></span></div>`:`<span class="pend">${T("pending")}</span>`}`; return; }
    // groups
    let html="";
    let anyPending=false;
    s.subcategories.forEach(sub=>{
      const its=s.items.filter(i=>i.subcategory_ar===sub && !CONFIG.hiddenItems.includes(i.id) && (i.approved || CONFIG.showPendingItems));
      if(!its.length) return;
      html+=`<div class="grp"><h3>${subName(s,sub)}</h3>`;
      its.forEach(it=>{ html+=rowHtml(it); if(!it.approved) anyPending=true; });
      html+=`</div>`;
    });
    if(anyPending) html+=`<p class="pnote">${T("pendNote")}</p>`;
    sc.grps.innerHTML=html;
    renderSheetBtn(sc);
  });
  rail.querySelectorAll("button").forEach(b=>{ if(b.classList.contains("closed")){ const [o,c]=JSON.parse(b.dataset.hrs); const sec=byId[b.dataset.sec];
      const t=x=>lang==="ar"?(x<12?`${x} ص`:`${x===12?12:x-12} م`):(x<12?`${x} AM`:`${x===12?12:x-12} PM`);
      b.textContent=`${secName(sec)} · ${T("hours").replace("{o}",t(o)).replace("{c}",t(c))}`; b.title=b.textContent; return; }
    const s=SECTIONS.find(x=>x.id===b.dataset.sec); b.textContent=secName(s); });
  renderCart();
}
function renderSheetBtn(sc){}
function rowHtml(it){
  const key=it.id; const inCart=cartQty(it);
  const opt = it.options ? `<div class="opts" data-item="${it.id}">${it.options.map((o,i)=>`<button aria-pressed="${(selOpt[it.id]||it.options[0].id)===o.id}" data-opt="${o.id}">${lang==="ar"?o.label_ar:o.label_en}</button>`).join("")}</div>`:"";
  if(!it.approved){
    return `<div class="row pending" data-item="${it.id}"><span class="chip"><span class="nm">${name(it)}</span></span><span class="chip"><span class="pend">${T("pending")}</span></span></div>`;
  }
  const kcal = it.calories_kcal!=null ? `<span class="kcal">${it.calories_kcal} ${T("kcal")}</span>`:``;
  const ctl = inCart>0 ? `<div class="qty"><button data-d="-1" aria-label="−">−</button><span>${inCart}</span><button data-d="1" aria-label="+">+</button></div>`
                       : `<button class="add" aria-label="${T("add")}: ${name(it)}">+</button>`;
  return `<div class="row" data-item="${it.id}"><span class="chip"><span class="nm">${name(it)}</span>${opt}</span><span class="chip">${kcal}${fmt(it.price_sar)}${ctl}</span></div>`;
}
const selOpt={};
function cartQty(it){ let q=0; for(const k in cart){ if(cart[k].id===it.id) q+=cart[k].qty; } return q; }

/* ---------- cart ---------- */
function save(){ try{ localStorage.setItem("armada-menu",JSON.stringify({lang,cart})); }catch(e){} }
function addToCart(id,d){
  const it=itemsById[id]; if(!it||!it.approved||it.price_sar==null) return; const opt = it.options ? (selOpt[id]||it.options[0].id) : null;
  const key = opt? id+"::"+opt : id;
  if(d>0){ cart[key]=cart[key]||{id,opt,qty:0}; cart[key].qty+=1; }
  else { // decrement: remove from the last-added variant of this item
    const keys=Object.keys(cart).filter(k=>cart[k].id===id); const k=keys[keys.length-1]; if(k){ cart[k].qty-=1; if(cart[k].qty<=0) delete cart[k]; }
  }
  save(); refreshItem(id); renderCart();
}
function refreshItem(id){
  document.querySelectorAll(`.row[data-item="${id}"]`).forEach(r=>{ const n=document.createElement("div"); n.innerHTML=rowHtml(itemsById[id]); const row=n.firstElementChild; r.replaceWith(row); flash(row); });
}
function flash(row){ // a light sweep travels around the item's chips so the guest sees exactly which item changed, then fades
  row.querySelectorAll(".chip").forEach(c=>{ const g=document.createElement("span"); g.className="ring"; c.appendChild(g); setTimeout(()=>g.remove(),1700); });
}
document.addEventListener("click",e=>{
  const add=e.target.closest(".row .add"); if(add){ addToCart(add.closest(".row").dataset.item,1); return; }
  const q=e.target.closest(".row .qty button"); if(q){ addToCart(q.closest(".row").dataset.item,+q.dataset.d); return; }
  const o=e.target.closest(".opts button"); if(o){ selOpt[o.closest(".opts").dataset.item]=o.dataset.opt; o.parentNode.querySelectorAll("button").forEach(b=>b.setAttribute("aria-pressed",b===o)); return; }
  const cq=e.target.closest(".cl .qty button"); if(cq){ const k=cq.closest(".cl").dataset.key; cart[k].qty+=+cq.dataset.d; if(cart[k].qty<=0) delete cart[k]; save(); renderCart(); refreshItem(k.split("::")[0]); return; }
  const rm=e.target.closest(".cl .rm"); if(rm){ const k=rm.closest(".cl").dataset.key; const id=cart[k].id; delete cart[k]; save(); renderCart(); refreshItem(id); return; }
});
function lines(){
  return Object.keys(cart).filter(k=>itemsById[cart[k].id] && itemsById[cart[k].id].approved && itemsById[cart[k].id].price_sar!=null).map(k=>{ const c=cart[k]; const it=itemsById[c.id]; const o=c.opt&&it.options?it.options.find(x=>x.id===c.opt):null;
    const delta=o?o.price_delta_sar:0; const unit=it.price_sar+delta;
    const label = name(it)+(o?` (${lang==="ar"?o.label_ar:o.label_en})`:"");
    return {key:k,label,qty:c.qty,unit,sum:unit*c.qty}; });
}
function renderCart(){
  const L=lines(); const total=L.reduce((a,l)=>a+l.sum,0); const n=L.reduce((a,l)=>a+l.qty,0);
  const cc=document.getElementById("cartCount"); if(cc.textContent!==String(n||"")){ cc.textContent=n||""; const f=document.getElementById("cartBtn"); f.classList.remove("pop"); void f.offsetWidth; f.classList.add("pop"); }
  const list=document.getElementById("cartList");
  list.innerHTML = L.length? L.map(l=>`<div class="cl" data-key="${l.key}"><div class="nm">${l.label}<small>${l.qty} × ${l.unit} ${T("sar")}</small></div>${fmt(l.sum)}
     <div class="line"><div class="qty"><button data-d="-1" aria-label="−">−</button><span>${l.qty}</span><button data-d="1" aria-label="+">+</button></div><button class="rm">${T("remove")}</button></div></div>`).join("")
     : `<p class="empty">${T("empty")}</p>`;
  document.getElementById("cartTotal").innerHTML=fmt(total);
  const msg=orderMessage(L,total);
  const wa=document.getElementById("waBtn"), cp=document.getElementById("copyBtn"), hint=document.getElementById("cartHint");
  const num=(CONFIG.whatsappNumber||"").replace(/\D/g,"");
  if(num){ wa.style.display="flex"; wa.href=`https://wa.me/${num}?text=${encodeURIComponent(msg)}`; wa.innerHTML=`<svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.885-9.885 9.885m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg><span>${T("wa")}</span>`; wa.setAttribute("aria-disabled",!L.length); cp.classList.add("ghost"); cp.classList.remove("primary"); hint.textContent=T("hintNumber"); }
  else { wa.style.display="none"; cp.classList.remove("ghost"); cp.classList.add("primary"); hint.textContent=T("hintNoNumber"); }
  cp.textContent=T("copy"); cp.disabled=!L.length; cp.setAttribute("aria-disabled",!L.length); cp.onclick=()=>copyText(msg);
  const cl=document.getElementById("clearBtn"); cl.textContent=T("clearAll"); cl.hidden=!L.length;
  document.getElementById("clearTop").hidden=!L.length;
}
function orderMessage(L,total){
  const s=T("sar"); const b=[T("orderTitle"),""];
  L.forEach(l=>b.push(`• ${l.label}\n  ${T("orderLine")}: ${l.qty} × ${l.unit} ${s} = ${l.sum} ${s}`));
  b.push("",`${T("total")}: ${total} ${s}`); return b.join("\n");
}
async function copyText(t){
  try{ await navigator.clipboard.writeText(t); }catch(e){ const ta=document.createElement("textarea"); ta.value=t; document.body.appendChild(ta); ta.select(); try{document.execCommand("copy")}catch(_){} ta.remove(); }
  toast(T("copied"));
}
let toastT; function toast(m){ const t=document.getElementById("toast"); t.textContent=m; t.classList.add("on"); clearTimeout(toastT); toastT=setTimeout(()=>t.classList.remove("on"),1800); }

const drawer=document.getElementById("drawer"), dim=document.getElementById("dim");
function openCart(o){ drawer.classList.toggle("on",o); dim.classList.toggle("on",o); drawer.setAttribute("aria-hidden",!o); document.getElementById("cartBtn").setAttribute("aria-expanded",o); }
document.getElementById("cartBtn").onclick=()=>openCart(true);
function clearCart(){ const ids=[...new Set(Object.values(cart).map(c=>c.id))]; cart={}; save(); renderCart(); ids.forEach(refreshItem); openCart(false); toast(T("cleared")); }
document.getElementById("clearBtn").onclick=clearCart; document.getElementById("clearTop").onclick=clearCart;
document.getElementById("closeCart").onclick=()=>openCart(false); dim.onclick=()=>openCart(false);
document.addEventListener("keydown",e=>{ if(e.key==="Escape") openCart(false); });
document.getElementById("home").onclick=e=>{e.preventDefault();scrollTo({top:0,behavior:RM?"auto":"smooth"});};


/* ---------- frame engine ---------- */
const FW=720, FH=898;
let vw=0,vh=0,dpr=1;
function frameSet(){ // responsive set: the small set only when the drawn frame needs ≤ 520 device px of width
  if(MODE!=="files") return "desktop"; const sets=FRAMES[SECTIONS[0].folder].sets; if(!sets.mobile) return "desktop";
  const need = drawScale()*FW*dpr; return need<=sets.mobile.width*1.08 ? "mobile" : "desktop";
}
function listTop(){ // mobile: the compact list occupies the bottom of the viewport
  return isNarrow()? Math.round(vh*(1-0.33)) : vh;
}
function layout(){
  const W=vw*dpr,H=vh*dpr; const sW=W/FW, sH=H/FH;
  if(!isNarrow()){ const s=Math.min(sH, 1.25*dpr); return {W,H,s,dw:FW*s,dh:FH*s}; }   // never upscale the 720 source beyond 1.25× — extend the scene instead
  const s=Math.min(sH, sW*1.22, 1.25*dpr); return {W,H,s,dw:FW*s,dh:FH*s};
}
function drawScale(){ return layout().s/dpr; }
function setupCanvases(){
  vw=innerWidth; const st=document.querySelector(".stage"); vh=st?st.clientHeight:innerHeight; dpr=Math.min(devicePixelRatio||1,2);
  scenes.forEach(sc=>{ sc.frame.width=Math.round(vw*dpr); sc.frame.height=Math.round(vh*dpr); sc.glow.width=48; sc.glow.height=Math.round(48*vh/vw); sc.drawn=-1; });
  fitLengths();
}
function fitLengths(){ // scroll distance = base length + however much of the list does not fit on screen
  if(RM) return;
  scenes.forEach(sc=>{ const base=sc.sec.id==="snacks"?CONFIG.snacksLength:CONFIG.sceneLength;
    sc.ov = sc.panel ? Math.max(0, sc.panel.scrollHeight - sc.panel.clientHeight) : 0;
    sc.el.style.setProperty("--len", (base + sc.ov/Math.max(1,vh)).toFixed(3)); });
}
function nearestLoaded(sc,i){
  if(sc.imgs[i]&&sc.imgs[i].ok) return sc.imgs[i];
  for(let d=1;d<sc.count;d++){ const a=sc.imgs[i-d], b=sc.imgs[i+d]; if(a&&a.ok) return a; if(b&&b.ok) return b; }
  return null;
}
function draw(sc,i,force){
  const img=nearestLoaded(sc,i); if(!img) return false;
  const key=img.i;
  if(!force && sc.drawn===key) return true;
  const ctx=sc.frame.getContext("2d"); const L=layout(); const {W,H,dw,dh}=L;
  const dx=(W-dw)/2, dy=L.cy!=null ? L.cy-dh/2 : (H-dh)/2;
  ctx.setTransform(1,0,0,1,0,0); ctx.globalCompositeOperation="source-over"; ctx.clearRect(0,0,W,H);
  ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality="high";
  ctx.drawImage(img,dx,dy,dw,dh);
  ctx.globalCompositeOperation="destination-out";
  if(dw<W-1){ const f=Math.min(dw*0.14,150*dpr);
    let g=ctx.createLinearGradient(dx,0,dx+f,0); g.addColorStop(0,"rgba(0,0,0,1)"); g.addColorStop(1,"rgba(0,0,0,0)"); ctx.fillStyle=g; ctx.fillRect(dx-1,0,f+1,H);
    g=ctx.createLinearGradient(dx+dw,0,dx+dw-f,0); g.addColorStop(0,"rgba(0,0,0,1)"); g.addColorStop(1,"rgba(0,0,0,0)"); ctx.fillStyle=g; ctx.fillRect(dx+dw-f,0,f+1,H); }
  if(dy>0.5 || dy+dh<H-0.5){ const f=Math.min(dh*0.12,120*dpr);
    let g=ctx.createLinearGradient(0,dy,0,dy+f); g.addColorStop(0,"rgba(0,0,0,1)"); g.addColorStop(1,"rgba(0,0,0,0)"); ctx.fillStyle=g; ctx.fillRect(0,dy-1,W,f+1);
    g=ctx.createLinearGradient(0,dy+dh,0,dy+dh-f); g.addColorStop(0,"rgba(0,0,0,1)"); g.addColorStop(1,"rgba(0,0,0,0)"); ctx.fillStyle=g; ctx.fillRect(0,dy+dh-f,W,f+1); }
  ctx.globalCompositeOperation="source-over";
  // extended scene: a tiny cover-scaled copy of the same frame behind the sharp one, blurred by CSS (the sharp frame itself is never blurred)
  const gc=sc.glow.getContext("2d"); const gw=sc.glow.width,gh=sc.glow.height; const gs=Math.max(gw/FW,gh/FH);
  gc.fillStyle="#211217"; gc.fillRect(0,0,gw,gh); gc.drawImage(img,(gw-FW*gs)/2,(gh-FH*gs)/2,FW*gs,FH*gs);
  sc.drawn=key; return true;
}

/* loading: only a window around the frame being shown, then a lookahead in the scroll direction, then a slow trickle
   through the rest of the active scene. Neighbouring scenes get their first frames when they come within a viewport. */
const MAXC=5, NEAR=6, AHEAD=20; let inflight=0; const queue=[]; let activeScene=null;
function want(sc,i){ if(i<0||i>=sc.count||sc.imgs[i]) return; const img=new Image(); img.i=i; img.ok=false; img.sc=sc; sc.imgs[i]=img; queue.push(img); }
function pump(){
  if(inflight>=MAXC||!queue.length) return;
  const A=activeScene; queue.sort((a,b)=>((a.sc===A?0:1e6)+Math.abs(a.i-a.sc.idx))-((b.sc===A?0:1e6)+Math.abs(b.i-b.sc.idx)));
  while(inflight<MAXC && queue.length){ const img=queue.shift(); inflight++;
    img.onload=()=>{ img.ok=true; img.sc.loaded++; inflight--; requestDraw(false); pump(); };
    img.onerror=()=>{ inflight--; img.sc.imgs[img.i]=null; pump(); };
    img.src=img.sc.url(img.i); }
}
function scheduleWindow(sc,i,dir){
  for(let d=0; d<=NEAR; d++){ want(sc,i+d); want(sc,i-d); }
  for(let d=NEAR+1; d<=AHEAD; d++) want(sc, i + d*(dir>=0?1:-1));
  if(sc===activeScene && inflight===0 && !queue.length){ // trickle: next few unloaded frames beyond the lookahead
    let n=0; for(let k=i+AHEAD+1; k<sc.count && n<4; k++) if(!sc.imgs[k]){ want(sc,k); n++; }
    for(let k=i-NEAR-1; k>=0 && n<4; k--) if(!sc.imgs[k]){ want(sc,k); n++; }
  }
  pump();
}

let activeIdx=0, lastY=0, scrollDir=1, rafPending=false, forceNext=false;
function requestDraw(force){ if(force) forceNext=true; if(rafPending) return; rafPending=true; requestAnimationFrame(()=>{ rafPending=false; const f=forceNext; forceNext=false; tick(f); }); }
function progressOf(sc){ const r=sc.el.getBoundingClientRect(); const range=Math.max(1,r.height-sc.stage.clientHeight); return Math.min(1,Math.max(0,-r.top/range)); }
function tick(force){
  const y=scrollY; scrollDir = y>=lastY ? 1 : -1; lastY=y; let act=0;
  scenes.forEach((sc,si)=>{ const r=sc.el.getBoundingClientRect(); if(r.top<=vh*0.5 && r.bottom>vh*0.5) act=si; });
  if(scenes[act]!==activeScene){ activeScene=scenes[act]; }
  let pendingLoads=false;
  scenes.forEach((sc,si)=>{
    const r=sc.el.getBoundingClientRect();
    const near = r.bottom>-vh*0.5 && r.top<vh*1.5;
    sc.visible = near;
    if(!near){ if(sc.panel) sc.panel.classList.remove("in"); sc.ttl.classList.remove("in"); return; }
    const p=progressOf(sc);
    const i = RM ? sc.count-1 : Math.round(p*(sc.count-1));
    sc.idx=i;
    if(RM){ want(sc,sc.count-1); pump(); }
    else if(r.top<vh*1.05 && r.bottom>-vh*0.1) scheduleWindow(sc,i,sc===activeScene?scrollDir:1);
    else { want(sc,0); pump(); }
    if(sc.panel && !RM && sc.ov>0) sc.panel.scrollTop = p*sc.ov;   // the list glides in step with the frames
    const ok=draw(sc,i,force);
    const exact = sc.imgs[i]&&sc.imgs[i].ok; if(!exact) pendingLoads=true;
    sc.lo.classList.toggle("on",!ok);
    const inView = r.top<vh && r.bottom>0;   // overlay travels with its scene edge, so the next section arrives with its title and items already in place
    sc.ttl.classList.toggle("in", RM || inView || si===0 && r.top>=0);
    if(sc.panel) sc.panel.classList.toggle("in", RM || inView || si===0 && r.top>=0);
  });
  if(act!==activeIdx||force){ activeIdx=act; rail.querySelectorAll("button").forEach((b,i)=>b.setAttribute("aria-current",i===act)); const ab=rail.children[act]; if(ab) ab.scrollIntoView({block:"nearest",inline:"center",behavior:"smooth"}); }
}
addEventListener("scroll",()=>requestDraw(false),{passive:true});
addEventListener("resize",()=>{ setupCanvases(); requestDraw(true); });
addEventListener("orientationchange",()=>setTimeout(()=>{setupCanvases();requestDraw(true);},200));

buildScenes();
activeScene=scenes[0];
if(RM){ want(scenes[0],scenes[0].count-1); } else { want(scenes[0],0); scheduleWindow(scenes[0],0,1); }
pump();
requestDraw(true);
